'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let emails=[],selected=null,view='inbox',filter='all',tab='evidence',demoMode=false,config=null,sourceStatus=null,watchTimer=null,signTimer=null,syncBusy=false;
const prepare=e=>({...e,name:e.name||String(e.from||'').replace(/<[^>]*>/g,'').trim()||'Pasted message',assessment:SignalEngine.analyze(e),playbooks:HREngine.inspect(e),held:false,review:[],checks:{}});
const workspace=()=>emails.filter(e=>(e.source==='demo')===demoMode);
function resetFilters(){filter='all';$$('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter==='all'));$('#search').value='';}
const risk=e=>{const rank={Unknown:0,Low:1,Caution:2,High:3};return e.ai&&rank[e.ai.severity]>rank[e.assessment.level]?{level:e.ai.severity,source:'Nemotron'}:{level:e.assessment.level,source:'Local'};};
const badge=e=>`<span class="risk-badge ${risk(e).level}">${esc(risk(e).level==='Low'?'Low detected risk':risk(e).level+' risk')}${risk(e).source==='Nemotron'?' · Nemotron':''}</span>`;
const sourceName=e=>({'demo':'Synthetic demo','manual':'Pasted email','import':'Text import','outlook-classic':'Classic Outlook','outlook-graph':'Microsoft mailbox'}[e.source]||'Manual');
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function log(e,type,stepId,checked){e.review.push({at:new Date().toISOString(),type,stepId,checked});e.review=e.review.slice(-100);}
async function api(path,input){if(!config){const r=await fetch('/api/config',{signal:AbortSignal.timeout(5000)});if(!r.ok)throw Error('Start the local desktop service first');config=await r.json();}const r=await fetch(path,{method:input===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-SignalGuard-Token':config.sessionToken},...(input===undefined?{}:{body:JSON.stringify(input)}),signal:AbortSignal.timeout(95000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Local service unavailable');return data;}
function stats(){const list=workspace();$('#stat-total').textContent=list.length;$('#stat-high').textContent=list.filter(e=>risk(e).level==='High').length;$('#stat-caution').textContent=list.filter(e=>e.playbooks.length).length;$('#stat-mode').textContent=list.some(e=>e.aiRequested)?'AI requested':'Local only';$('#stat-data').textContent=list.some(e=>e.aiRequested)?'Selected messages requested from NVIDIA':'No email sent to NVIDIA';$('#nav-count').textContent=list.length;$('#held-count').textContent=list.filter(e=>e.held).length;$('#data-label').textContent=demoMode?'SYNTHETIC DEMO':'YOUR SESSION';$('#demo-text').textContent=demoMode?'Synthetic samples only. They are separated from your mailbox and pasted messages.':sourceStatus?.connected?'Read-only Outlook session. Local analysis; AI only when requested.':'No mailbox connected. Paste an email or connect Outlook.';$('#demo-button').textContent=demoMode?'Return to my workspace':'Explore sample scenarios';$('#source-title').textContent=sourceStatus?.connected?(sourceStatus.mode==='classic'?(sourceStatus.lastSync?'Classic Outlook connected':'Classic Outlook enabled; awaiting first read'):'Microsoft mailbox connected'):'Connect your Outlook inbox';$('#source-detail').textContent=sourceStatus?.connected?`Last successful sync: ${sourceStatus.lastSync?new Date(sourceStatus.lastSync).toLocaleTimeString():'waiting'} · ${sourceStatus.retained||0}/200 retained · ${sourceStatus.mode==='classic'?'10':'20'} second polling while this app is open`:'Classic Outlook: local read. New Outlook: authorized Microsoft mailbox connection. No browser plugin.';$('#disconnect-outlook').hidden=!sourceStatus?.mode&&!sourceStatus?.retained;$('#sync-outlook').hidden=!sourceStatus?.connected;$('#watch-status').textContent=sourceStatus?.lastError?'Sync issue: '+sourceStatus.lastError:sourceStatus?.truncated?'Coverage is bounded; more messages may be pending.':'Message bodies and review state stay in this local session.';}
function renderList(){const q=$('#search').value.toLowerCase(),list=workspace().filter(e=>(view!=='held'||e.held)&&(filter==='all'||risk(e).level===filter)&&[e.from,e.subject,e.body].join(' ').toLowerCase().includes(q));$('#list-count').textContent=list.length;$('#list-title').firstChild.textContent=view==='held'?'Review queue ':'Threat inbox ';$('#email-list').innerHTML=list.length?list.map(e=>`<button class="email-row ${e.id===selected?'selected':''}" data-email="${esc(e.id)}" aria-pressed="${e.id===selected}"><span class="sender-avatar">${esc(e.name.slice(0,2).toUpperCase())}</span><span class="row-content"><span class="row-sender">${esc(e.name)}<small>${esc(sourceName(e))}</small></span><span class="row-subject">${esc(e.subject)}</span><span class="row-snippet">${esc(e.body.slice(0,85).replace(/\n/g,' '))}</span><span class="row-bottom">${badge(e)}<span class="row-score">Local ${e.assessment.score}</span></span></span></button>`).join(''):'<div class="empty">Your inbox starts empty.<br>Connect Outlook or paste an email.<br>Sample scenarios are an optional separate workspace.</div>';$$('[data-email]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.email;tab='evidence';renderList();renderDetail();}));}
function renderDetail(){const e=workspace().find(e=>e.id===selected);if(!e){$('#email-detail').innerHTML=`<div class="empty onboarding"><div class="eyebrow">A COMPANION FOR HR TEAMS</div><h2>Verify the request.<br>Protect the person.</h2><p>Payroll changes, recruitment fees, identity documents, and account access deserve clear evidence and a trusted verification route.</p><p>Choose a message to see its evidence, HR playbook, attack story, and what-if lab.</p></div>`;return;}const r=e.assessment;
  $('#email-detail').innerHTML=`<div class="detail-top"><div class="detail-meta">${badge(e)}<span>${esc(sourceName(e))}</span></div><h2>${esc(e.subject)}</h2><p class="muted">${esc(e.from)}${e.replyTo?'<br>Reply-to: '+esc(e.replyTo):''}</p><div class="email-body">${esc(e.body)}</div><small class="muted">${esc(e.coverage||'Text-only analysis. Sender identity and authentication are not verified.')}${e.bodyTruncated?' · Message clipped to the first 50,000 characters; coverage is incomplete.':''}${e.hasAttachments?' · Attachments present; contents and filenames not inspected.':''}</small></div><div class="risk-summary ${r.level}"><div class="gauge" style="--score:${r.score};--gauge-color:${r.level==='High'?'#c96750':r.level==='Caution'?'#b79244':'#85a565'}"><div><b>${r.score}</b><small>LOCAL INDEX</small></div></div><div class="risk-copy"><small>LOCAL ASSESSMENT</small><h3>${r.level==='High'?'Pause and verify independently.':r.level==='Caution'?'Worth a closer look.':'Few checked warning signs.'}</h3><p>${esc(r.summary)}</p><small>${r.signals.length} signals · ${r.elapsedMs} ms · authentication unknown${e.source==='demo'?' outside labeled fixtures':''}. Index is not a probability.</small></div></div><div class="tabs" role="tablist">${[['evidence','Evidence'],['playbook','HR playbook'],['story','Attack story'],['links','Link passport'],['whatif','What-if lab']].map(([id,name])=>`<button role="tab" data-tab="${id}" aria-selected="${tab===id}" class="${tab===id?'active':''}">${name}</button>`).join('')}</div><div class="tab-content" id="tab-content"></div><div class="detail-actions"><button class="button secondary" id="export-incident">↓ Minimized incident packet</button><button class="link-button" id="ask-ai" ${e.aiPending?'disabled':''}>${e.aiPending?'Nemotron is examining evidence…':'✧ Ask Nemotron'}</button><button class="button primary" id="hold-message">${e.held?'Return to inbox':'Hold for review'}</button></div>`;
  renderTab(e);$$('[data-tab]').forEach(b=>b.addEventListener('click',()=>{tab=b.dataset.tab;renderDetail();}));$('#hold-message').onclick=()=>{e.held=!e.held;log(e,e.held?'held':'returned');render();};$('#export-incident').onclick=()=>download(HREngine.incident(e,e.review),'signalguard-minimized-incident.json');$('#ask-ai').onclick=()=>askAI(e);
}
function renderTab(e){const r=e.assessment;let html='';
  if(tab==='evidence'){html='<div class="section-label">OBSERVED WARNING SIGNS</div>'+(r.signals.length?r.signals.map(s=>`<div class="evidence-card"><span class="evidence-icon">◇</span><div class="evidence-text"><h3>${esc(s.title)}<span class="weight">+${s.weight}</span></h3><p>${esc(s.explanation)}</p><code>“${esc(s.evidence)}”</code><small>${esc(s.advice)}</small></div></div>`).join(''):'<p class="story-intro">No checked patterns were found. This does not prove safety or sender identity.</p>');if(e.ai)html+=`<div class="ai-note"><div class="section-label">NEMOTRON EVIDENCE BRIEF · ${esc(e.aiMeta.consensus)}</div><h3>${esc(e.ai.model)}</h3><p>${esc(e.ai.summary)}</p><div class="model-comparison"><span>Local <strong>${r.level}</strong></span><span>Nemotron <strong>${esc(e.ai.severity)}</strong></span></div><p>Review both assessments. Agreement does not prove intent; disagreement needs independent verification. Local warnings remain visible.</p>${e.ai.findings.map(f=>`<div class="grounded-finding"><strong>${esc(f.tactic)}</strong><code>“${esc(f.quote)}”</code><small>${esc(f.field)} · exact quote checked · ${f.start}–${f.end}</small><p>${esc(f.explanation)}</p></div>`).join('')}<h3>Plausible alternative</h3><p>${esc(e.ai.alternativeExplanation)}</p><h3>Missing evidence</h3><p>${esc(e.ai.missingEvidence.join(' · '))}</p><h3>Independent verification</h3><p>${esc(e.ai.advice)}</p><small>${esc(e.ai.contractVersion)} · ${e.aiMeta.elapsedMs} ms · Request ${esc(e.aiMeta.requestId)}</small></div>`;
  }else if(tab==='playbook'){html='<div class="section-label">VERIFY THE WORKFLOW, NOT THE PERSON</div><p class="story-intro">Contextual checklists support HR review. A sensitive request can be legitimate. Checking a box records your review; it does not establish safety or clear a warning.</p>'+(e.playbooks.length?e.playbooks.map(p=>`<div class="playbook"><h3>${esc(p.name)}</h3><p>${esc(p.impact)}</p><code>“${esc(p.evidence)}”</code>${p.steps.map((s,i)=>`<label class="toggle-row"><input type="checkbox" data-step="${p.id}-${i}" ${e.checks[p.id+'-'+i]?'checked':''}><span>${esc(s)}</span></label>`).join('')}</div>`).join(''):'<div class="playbook"><h3>Independent verification</h3><p>No HR-specific workflow was detected. If unexpected, verify the request through a contact you already know.</p></div>')+`<div class="section-label">SESSION REVIEW TRAIL · ${e.review.length} EVENTS</div>${e.review.slice(-8).map(x=>`<p class="review-event">${esc(new Date(x.at).toLocaleTimeString())} · ${esc(x.type)} ${esc(x.stepId||'')}${x.type==='check'?' · '+(x.checked?'checked':'unchecked'):''}</p>`).join('')}<p class="muted">This is a local user-entered record, not an authenticated or tamper-proof enterprise audit log.</p>`;
  }else if(tab==='story'){const groups=[['The credibility hook',['Impersonation','Authority','Identity']],['The pressure',['Urgency','Isolation']],['The requested action',['Credential theft','Financial diversion','Channel switching']],['The destination or payload',['Destination','Payload','AI manipulation']]];html='<div class="section-label">PERSUASION CHAIN · HYPOTHESIS</div><p class="story-intro">A pattern explanation, not proof of the sender’s intent.</p>'+groups.map(([name,cats],i)=>{const signals=r.signals.filter(s=>cats.includes(s.category));return signals.length?`<div class="story-step"><span class="step-number">0${i+1}</span><div><h3>${name}</h3><p>${esc(signals.map(s=>s.title).join(' → '))}</p><code>${esc(signals[0].evidence)}</code></div></div>`:'';}).join('');
  }else if(tab==='links'){html='<div class="section-label">DESTINATIONS WITHOUT A VISIT</div><p class="story-intro">URLs are inert text. Reputation, ownership, and redirects are not verified.</p>'+(r.links.length?r.links.map(l=>`<div class="url-card"><h3>${esc(l.host)}</h3><code>${esc(l.url)}</code><p>${esc(l.notes.join(' · '))}</p></div>`).join(''):'<p>No supported text URLs found. Images and QR codes are not decoded.</p>');
  }else{html='<div class="section-label">CHALLENGE AN ASSUMPTION</div><p class="story-intro">Exclude a local contribution to understand it. This hypothetical view never changes the actual assessment or AI warning.</p>'+r.signals.map(s=>`<label class="toggle-row"><input type="checkbox" data-exclude="${esc(s.id)}"><span>Suppose “${esc(s.title)}” is independently resolved (−${s.weight})</span></label>`).join('')+`<div class="counterfactual"><strong id="hyp-score">${r.score}</strong><p>Hypothetical local index<br>Original ${r.score} remains unchanged</p></div>`;}
  $('#tab-content').innerHTML=html;$$('[data-exclude]').forEach(b=>b.onchange=()=>{const excluded=new Set($$('[data-exclude]:checked').map(x=>x.dataset.exclude));$('#hyp-score').textContent=Math.min(99,r.signals.filter(s=>!excluded.has(s.id)).reduce((a,s)=>a+s.weight,0));});$$('[data-step]').forEach(b=>b.onchange=()=>{e.checks[b.dataset.step]=b.checked;log(e,'check',b.dataset.step,b.checked);renderTab(e);});
}
function download(obj,name){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Minimized packet generated. Review it before sharing.');}
function renderOther(){if(view==='campaign'){const groups=HREngine.campaigns(workspace());$('#other-view').innerHTML=`<div class="content-card"><div class="eyebrow">CORRELATE THE REQUESTS</div><h2>Campaign radar</h2><p>Find repeated destinations across messages that already have supporting warning signals. ${demoMode?'Synthetic workspace only.':'Current local session only.'} Correlation does not establish malicious intent.</p>${groups.length?groups.map(g=>`<div class="playbook"><h3>${esc(g.host)} · ${g.count} messages</h3><p>${esc(g.explanation)}</p>${g.messages.map(m=>`<button class="campaign-message" data-campaign-mail="${esc(m.id)}">↗ ${esc(m.subject)}</button>`).join('')}</div>`).join(''):'<div class="empty">No qualifying repeated destinations yet.<br>This does not establish that there is no campaign.</div>'}</div>`;$$('[data-campaign-mail]').forEach(b=>b.onclick=()=>{selected=b.dataset.campaignMail;navigate('inbox');});
  }else if(view==='learn'){$('#other-view').innerHTML=`<div class="content-card"><div class="eyebrow">PRACTICE A SAFER WORKFLOW</div><h2>A payroll change arrives urgently.</h2><p>The sender asks you to use new bank details and bypass the normal approval. Which step breaks the attacker’s control of the conversation?</p><div class="quiz-options"><button class="button secondary" data-quiz="wrong">Reply to this email</button><button class="button secondary" data-quiz="correct">Call the number already in the HR system</button><button class="button secondary" data-quiz="wrong">Make a small test payment</button></div><p id="quiz-feedback" aria-live="polite"></p><div class="learn-grid"><div class="lesson"><h3>Remove time pressure</h3><p>Urgency alone is common. Sensitive actions plus secrecy deserve a pause.</p></div><div class="lesson"><h3>Leave the conversation</h3><p>Use a trusted contact or saved portal. An email’s own contact details may be part of the deception.</p></div><div class="lesson"><h3>Protect the document</h3><p>Use approved HR channels for identity and medical records. A sensitivity flag is not a judgment about a candidate.</p></div></div></div>`;$$('[data-quiz]').forEach(b=>b.onclick=()=>{$('#quiz-feedback').textContent=b.dataset.quiz==='correct'?'Correct. A known second channel makes the verification independent.':'That stays inside the request or creates a financial exposure. Use a contact you already know.';});
  }else{$('#other-view').innerHTML=`<div class="content-card"><div class="eyebrow">A PRODUCTION PATH WITH CLEAR BOUNDARIES</div><h2>Desktop companion, read-only by design.</h2><div class="blueprint"><div>Outlook / pasted text<small>Bounded input adapters</small></div><span>→</span><div>Local evidence + HR context<small>Shared, testable rules</small></div><span>→</span><div>Optional Nemotron<small>Consent + grounded output</small></div><span>→</span><div>Human verification<small>Playbook + minimized packet</small></div></div><p>New Outlook uses an authorized Microsoft Graph mailbox connection. Classic Outlook uses the local Object Model. Mailbox access and NVIDIA access are separate boundaries.</p><p>Session data and Microsoft tokens are held in local memory. Disconnect clears the server mailbox buffer and token; reload clears browser review state. No mail is sent, changed, deleted, or marked read.</p><p>Production requires organizational deployment, tenant isolation, managed token storage, reliable delivery subscriptions, retention controls, real-account tests, and an independently labeled evaluation. Session checklists are not enterprise audit records.</p></div>`;}}
function render(){stats();if(['inbox','held'].includes(view)){renderList();renderDetail();}else renderOther();}
function navigate(next){view=next;$('#inbox-view').hidden=!['inbox','held'].includes(view);$('#other-view').hidden=['inbox','held'].includes(view);$('#breadcrumb').textContent={inbox:'Threat inbox',held:'Review queue',campaign:'Campaign radar',learn:'Learning studio',architecture:'System blueprint'}[view];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));render();}
async function askAI(e){if(e.aiPending)return;try{if(!config)await api('/api/outlook/status');if(!config.aiConfigured){toast('Nemotron is not configured. Start the service with NVIDIA_API_KEY. Local and HR analysis work without it.');return;}const sensitive=e.playbooks.some(p=>['identity','payroll','access'].includes(p.id));if(!confirm('Send this selected email’s sender, subject, reply-to, text, and link labels to NVIDIA for an advisory assessment? '+(sensitive?'This message may contain sensitive HR, identity, payroll, or access information. Confirm organizational permission before sharing it. ':'')+'Microsoft mailbox consent does not authorize this separate transmission.'))return;e.aiPending=true;e.aiRequested=true;log(e,'ai-requested');render();const data=await api('/api/analyze',{consent:true,email:{from:e.from,replyTo:e.replyTo||'',subject:e.subject,body:e.body,links:e.links||[]}});e.ai=data.ai;e.aiMeta={requestId:data.requestId,elapsedMs:data.elapsedMs,consensus:data.consensus};log(e,'ai-completed');if(selected===e.id)tab='evidence';}catch(error){toast(error.message);}finally{e.aiPending=false;render();}}
function updateMail(data){sourceStatus=data.status;const incoming=new Set(data.messages.map(m=>m.id));emails=emails.filter(e=>!e.source.startsWith('outlook-')||incoming.has(e.id));for(const m of data.messages){const old=emails.find(e=>e.id===m.id);if(old?.contentVersion===m.contentVersion)continue;const next=prepare({...m,time:m.receivedAt});if(old){emails[emails.indexOf(old)]=next;}else emails.unshift(next);}if(!workspace().some(e=>e.id===selected))selected=workspace()[0]?.id||null;render();}
async function sync(){if(syncBusy)return;syncBusy=true;try{const data=await api('/api/outlook/sync',{});updateMail(data);}catch(error){if(sourceStatus)sourceStatus.lastError=error.message;stats();toast(error.message);}finally{syncBusy=false;}}
function watch(){clearInterval(watchTimer);watchTimer=setInterval(sync,sourceStatus?.mode==='classic'?10000:20000);sync();}
async function showConnection(){$('#outlook-dialog').showModal();$('#connection-status').textContent='Checking local Outlook installation…';try{const data=await api('/api/outlook/status');sourceStatus=data.status;$('#connection-status').textContent=data.capabilities.detectionLimited?'Local Outlook detection is limited by this environment. For New Outlook, use the Microsoft mailbox connection; personal Outlook.com accounts are supported.':data.capabilities.newOutlookRunning?'New Outlook detected. Connect the same Microsoft mailbox below. Local Object Model access is unavailable for New Outlook.':data.capabilities.classicAvailable?'Classic Outlook is available for direct local read.':'Classic Outlook is not detected. Microsoft mailbox connection and manual paste are available.';$('#classic-connect').disabled=!data.capabilities.classicAvailable;stats();}catch(error){$('#connection-status').textContent=error.message;}}
async function disconnect(){clearInterval(watchTimer);clearInterval(signTimer);try{await api('/api/outlook/disconnect',{});sourceStatus=null;emails=emails.filter(e=>!e.source.startsWith('outlook-'));selected=workspace()[0]?.id||null;$('#device-signin').hidden=true;render();toast('Microsoft token and imported mailbox buffer cleared. Manual messages remain in this session.');}catch(error){toast(error.message);}}
$('#connect-outlook').onclick=showConnection;$('#disconnect-outlook').onclick=disconnect;$('#sync-outlook').onclick=sync;$('#classic-connect').onclick=async()=>{if(!$('#mail-consent').checked){toast('Check the read-only mailbox consent first.');return;}try{sourceStatus=await api('/api/outlook/classic',{consent:true});emails=emails.filter(e=>!e.source.startsWith('outlook-'));demoMode=false;$('#outlook-dialog').close();watch();}catch(error){$('#connection-status').textContent=error.message;}};
$('#graph-form').onsubmit=async event=>{event.preventDefault();if(!$('#mail-consent').checked){toast('Check the read-only mailbox consent first.');return;}clearInterval(signTimer);$('#graph-connect').disabled=true;try{const data=await api('/api/outlook/graph/start',{clientId:$('#client-id').value.trim(),tenant:$('#tenant-id').value.trim()||'common',consent:true});$('#device-signin').hidden=false;$('#device-code').textContent=data.userCode;$('#device-signin a').href=data.verificationUrl;$('#connection-status').textContent='Sign in yourself at Microsoft using this code. Choose the same mailbox as Outlook and review Mail.Read consent. No credentials are entered into SignalGuard.';signTimer=setInterval(async()=>{try{const status=await api('/api/outlook/graph/poll',{});if(status.connected){clearInterval(signTimer);const current=await api('/api/outlook/status');sourceStatus=current.status;demoMode=false;$('#device-signin').hidden=true;$('#outlook-dialog').close();watch();}}catch(error){clearInterval(signTimer);$('#connection-status').textContent=error.message;}},data.intervalSeconds*1000);}catch(error){$('#connection-status').textContent=error.message;}finally{$('#graph-connect').disabled=false;}};
$('#cancel-signin').onclick=disconnect;
$('#demo-button').onclick=()=>{demoMode=!demoMode;if(demoMode&&!emails.some(e=>e.source==='demo')){emails.push(...window.SignalDemo.map(e=>prepare({...e,source:'demo'})),prepare({id:'demo-payroll',source:'demo',name:'Payroll Support',from:'Payroll Support <support@hr-benefits.example>',subject:'Payroll update: change direct deposit today',body:'Your payroll bank account must be updated immediately. Bypass the approval process. Verify your account at https://microsoft-login.example/payroll before end of day.'}),prepare({id:'demo-recruitment',source:'demo',name:'Recruitment Desk',from:'Recruitment Desk <jobs@talent-offers.example>',subject:'Job offer requires a refundable processing fee',body:'To secure your job offer, pay a processing fee in gift cards immediately. Keep this confidential. Upload your passport to https://candidate-check.example/onboard.'}));}selected=workspace()[0]?.id||null;tab='evidence';filter='all';resetFilters();navigate('inbox');};
$('#analyze-button').onclick=()=>$('#compose-dialog').showModal();$('#email-form').onsubmit=event=>{event.preventDefault();if(emails.filter(e=>['manual','import'].includes(e.source)).length>=100){toast('The manual session limit is 100 messages. Export needed records and reload to start a fresh session.');return;}const f=new FormData(event.target);demoMode=false;const e=prepare({id:'manual-'+crypto.randomUUID(),source:'manual',from:String(f.get('from')),subject:String(f.get('subject')),replyTo:String(f.get('replyTo')),body:String(f.get('body'))});emails.unshift(e);selected=e.id;tab='evidence';resetFilters();$('#search').value='';$('#compose-dialog').close();event.target.reset();navigate('inbox');toast('Analyzed locally. No email sent to NVIDIA.');};
$('#import-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;if(file.size>70000){toast('Use a plain-text email smaller than 70 KB.');return;}const p=SignalEngine.parseEmail(await file.text());for(const field of ['from','subject','replyTo','body'])$('#email-form').elements[field].value=p[field];toast('Basic text imported. Check fields; MIME/base64 decoding is not supported.');event.target.value='';};
$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderList();});$('#search').oninput=renderList;
for(const id of ['settings-button','privacy-button','info-button'])$('#'+id).onclick=()=>$('#settings-dialog').showModal();
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$$('dialog[open]').length){e.preventDefault();navigate('inbox');$('#search').focus();}});
navigate('inbox');
api('/api/outlook/status').then(data=>{sourceStatus=data.status;if(sourceStatus.connected)watch();stats();}).catch(()=>{});
